const Progress = (props) => {
  const { setLinked, setCheckingLink } = props
  const notify = useNotify()
  let linkCheckDelay = 2000
  let linkChecks = 30
  const openedTab = useRef()

  useEffect(() => {
    httpClient('/api/lastfm/link/start')
      .then((response) => {
        const callbackEndpoint = baseUrl(
          `/api/lastfm/link/callback?state=${encodeURIComponent(response.json.state)}`
        )
        const callbackUrl = `${window.location.origin}${callbackEndpoint}`
        openedTab.current = openInNewTab(
          `https://www.last.fm/api/auth/?api_key=${config.lastFMApiKey}&cb=${encodeURIComponent(callbackUrl)}`
        )
      })
      .catch(() => setCheckingLink(false))
  }, [])

  const endChecking = (success) => {
    linkCheckDelay = null
    setCheckingLink(false)
    if (success) {
      notify('message.lastfmLinkSuccess', 'success')
    } else {
      notify('message.lastfmLinkFailure', 'warning')
    }
    setLinked(success)
  }

  useInterval(() => {
    httpClient('/api/lastfm/link')
      .then((response) => {
        let result = false
        if (response.json.status === true) {
          result = true
          endChecking(true)
        }
        return result
      })
      .then((result) => {
        if (!result && openedTab.current?.closed === true) {
          endChecking(false)
          result = true
        }
        return result
      })
      .then((result) => {
        if (!result && --linkChecks === 0) {
          endChecking(false)
        }
      })
      .catch(() => {
        endChecking(false)
      })
  }, linkCheckDelay)

  return <LinearProgress />
}

